//! Style action parity (ex-540).
//!
//! `tests/fixtures/style-actions.json` is upstream's own `perform` of every
//! action the styles panel and its keys trigger, at the pinned commit,
//! generated by `tools/goldens/style-actions-fixtures.mjs` on hand-written
//! scenes (shapes, lines that can close into polygons, freedraw, free and
//! bound text, sticky notes and their labels, bound and elbow arrows,
//! frames, groups, locked and deleted elements). Every case is replayed
//! through [`edit_actions::perform_style_action`] in upstream's test mode
//! after `reseed(1)` (seeds and version nonces from roughjs' `Random(1)`,
//! timestamps 1) with the text measured 10 px per UTF-16 code unit, and
//! compared with upstream's result: every element (every key, in order),
//! the app state keys the action changed and `captureUpdate`.

use excali_core::app_state::{get_default_app_state, AppState, AppStateEnv};
use excali_core::element::Element;
use excali_core::fractional_index::{ChangeStamp, SceneElementsMap};
use excali_core::restore::RestoreEnv;
use excali_editor::actions::ActionName;
use excali_editor::binding::{update_bound_elements_in_map, BindingEnv};
use excali_editor::edit_actions::{self, StyleEnv};
use excali_editor::scene::MutationEnv;
use excali_editor::store::CaptureUpdateAction;
use excali_editor::text_layout::TextLayouter;
use excali_text::text_measurements::{CharCountTextMetrics, CharWidthCache, TextMetricsProvider};
use serde_json::{json, Map, Value};

const FIXTURE: &str = include_str!("fixtures/style-actions.json");

fn cases() -> Vec<Value> {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("style-actions.json parses");
    let cases = fixture["cases"].as_array().expect("cases").clone();
    assert!(!cases.is_empty(), "no cases");
    cases
}

fn elements(case: &Value) -> Vec<Element> {
    case["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .map(|e| {
            Element::from_map(e.as_object().expect("an element").clone())
                .expect("an element upstream built")
        })
        .collect()
}

/// `v` with every number as a double (JSON has one number type).
fn numbers(v: &Value) -> Value {
    match v {
        Value::Number(n) => json!(n.as_f64().unwrap()),
        Value::Array(a) => Value::Array(a.iter().map(numbers).collect()),
        Value::Object(o) => Value::Object(o.iter().map(|(k, v)| (k.clone(), numbers(v))).collect()),
        other => other.clone(),
    }
}

/// Upstream's test mode after `reseed(1)`: `randomInteger()` (seeds and
/// version nonces) from roughjs' `Random(1)` in upstream's order,
/// timestamps 1, and upstream's text layout under its test metric.
struct Env {
    rng: excali_core::restore::TestEnv,
    layouter: TextLayouter<CharCountTextMetrics>,
    char_widths: CharWidthCache,
}

impl Env {
    fn new() -> Env {
        Env {
            rng: excali_core::restore::TestEnv::default(),
            layouter: TextLayouter::new(CharCountTextMetrics),
            char_widths: CharWidthCache::new(),
        }
    }
}

impl RestoreEnv for Env {
    fn now(&mut self) -> f64 {
        1.0
    }

    fn random_id(&mut self) -> String {
        self.rng.random_id()
    }

    fn random_integer(&mut self) -> f64 {
        self.rng.random_integer()
    }
}

impl MutationEnv for Env {
    fn random_integer(&mut self) -> f64 {
        self.rng.random_integer()
    }

    fn now(&mut self) -> f64 {
        1.0
    }
}

impl ChangeStamp for Env {
    fn version_nonce(&mut self) -> f64 {
        self.rng.random_integer()
    }

    fn updated(&mut self) -> f64 {
        1.0
    }
}

impl BindingEnv for Env {
    fn text(&mut self) -> (&dyn TextMetricsProvider, &mut CharWidthCache) {
        (&CharCountTextMetrics, &mut self.char_widths)
    }
}

/// The generator as a version stamp while the layouter is busy.
struct Stamp<'a>(&'a mut excali_core::restore::TestEnv);

impl ChangeStamp for Stamp<'_> {
    fn version_nonce(&mut self) -> f64 {
        self.0.random_integer()
    }

    fn updated(&mut self) -> f64 {
        1.0
    }
}

/// A stamp and the metric as a [`BindingEnv`], for the arrows a sticky
/// note's layout moves.
struct StampBinding<'a> {
    stamp: &'a mut dyn ChangeStamp,
    char_widths: &'a mut CharWidthCache,
}

impl MutationEnv for StampBinding<'_> {
    fn random_integer(&mut self) -> f64 {
        self.stamp.version_nonce()
    }

    fn now(&mut self) -> f64 {
        self.stamp.updated()
    }
}

impl BindingEnv for StampBinding<'_> {
    fn text(&mut self) -> (&dyn TextMetricsProvider, &mut CharWidthCache) {
        (&CharCountTextMetrics, self.char_widths)
    }
}

impl StyleEnv for Env {
    fn redraw_text_bounding_box(
        &mut self,
        elements: &mut SceneElementsMap,
        text_id: &str,
        container_id: Option<&str>,
    ) -> Result<(), String> {
        let char_widths = &mut self.char_widths;
        let mut stamp = Stamp(&mut self.rng);
        self.layouter.redraw_text_bounding_box(
            &mut stamp,
            elements,
            text_id,
            container_id,
            &mut |stamp, elements, id| {
                let mut env = StampBinding {
                    stamp,
                    char_widths: &mut *char_widths,
                };
                update_bound_elements_in_map(elements, id, &SceneElementsMap::new(), &mut env);
                Ok(())
            },
        )
    }
}

/// The app state a case's action runs in: upstream's defaults in test mode
/// with the case's keys.
fn case_app_state(case: &Value) -> AppState {
    let mut app_state = get_default_app_state(&AppStateEnv {
        test_env: true,
        ..AppStateEnv::default()
    });
    for (k, v) in case["appState"].as_object().expect("appState") {
        app_state.insert(k.clone(), v.clone());
    }
    app_state
}

fn capture_name(capture: CaptureUpdateAction) -> &'static str {
    match capture {
        CaptureUpdateAction::Immediately => "IMMEDIATELY",
        CaptureUpdateAction::Eventually => "EVENTUALLY",
        CaptureUpdateAction::Never => "NEVER",
    }
}

/// The elements an action returned, compared with upstream's in order and
/// one by one, every key (the drawn seeds and nonces included).
fn assert_elements(got: &[Element], want: &Value, what: &str) {
    let got: Vec<Value> = got
        .iter()
        .map(|e| numbers(&Value::Object(e.to_map())))
        .collect();
    let want: Vec<Value> = want
        .as_array()
        .expect("elements")
        .iter()
        .map(numbers)
        .collect();
    let got_ids: Vec<&Value> = got.iter().map(|e| &e["id"]).collect();
    let want_ids: Vec<&Value> = want.iter().map(|e| &e["id"]).collect();
    assert_eq!(got_ids, want_ids, "{what}: order");
    for (g, w) in got.iter().zip(&want) {
        assert_eq!(g, w, "{what}: element {}", w["id"]);
    }
}

/// The app state keys the action set over `before`: each key upstream
/// changed holds upstream's value, and every other key set keeps its value.
fn assert_app_state(got: &Map<String, Value>, before: &AppState, want: &Value, what: &str) {
    let want = want.as_object().expect("appState");
    for (key, value) in want {
        let after = got.get(key).or_else(|| before.get(key)).map(numbers);
        assert_eq!(after, Some(numbers(value)), "{what}: {key}");
    }
    for (key, value) in got {
        if !want.contains_key(key) {
            assert_eq!(
                Some(numbers(value)),
                before.get(key).map(numbers),
                "{what}: {key} changed"
            );
        }
    }
}

#[test]
fn style_actions_match_upstream() {
    let mut actions = std::collections::BTreeSet::new();
    for case in cases() {
        let what = case["id"].as_str().unwrap();
        let name = case["action"].as_str().unwrap();
        actions.insert(name.to_owned());
        let action = ActionName::from_name(name).unwrap_or_else(|| panic!("action {name}"));
        let scene = elements(&case);
        let app_state = case_app_state(&case);
        let mut env = Env::new();
        let got = edit_actions::perform_style_action(
            action,
            &scene,
            &app_state,
            &case["value"],
            &mut env,
        );
        let want = &case["result"];
        if want.is_null() {
            assert_eq!(got, None, "{what}: upstream returns false");
            continue;
        }
        let got = got.unwrap_or_else(|| panic!("{what}: upstream performs"));
        if want["elements"].is_null() {
            assert_eq!(got.elements, None, "{what}: upstream returns no elements");
        } else {
            let next = got.elements.clone().unwrap_or_else(|| scene.clone());
            assert_elements(&next, &want["elements"], what);
        }
        assert_app_state(&got.app_state, &app_state, &want["appState"], what);
        assert_eq!(
            capture_name(got.capture_update()),
            want["captureUpdate"].as_str().unwrap(),
            "{what}: captureUpdate"
        );
    }
    // every action of the styles panel is covered
    assert_eq!(actions.len(), 29, "{actions:?}");
}

#[test]
fn other_actions_are_not_style_actions() {
    let mut env = Env::new();
    let app_state = case_app_state(&json!({ "appState": {} }));
    for action in [
        ActionName::Undo,
        ActionName::SelectAll,
        ActionName::ChangeArrowProperties,
    ] {
        assert_eq!(
            edit_actions::perform_style_action(action, &[], &app_state, &Value::Null, &mut env),
            None,
            "{action:?}"
        );
    }
}
